ALTER TABLE "strength_plans" DROP CONSTRAINT "strength_plans_fields";--> statement-breakpoint
ALTER TABLE "strength_plans" ADD COLUMN "is_draft" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "strength_plans" ADD CONSTRAINT "strength_plans_fields" CHECK ("strength_plans"."version">0 and char_length(btrim("strength_plans"."title")) between 1 and 160 and char_length("strength_plans"."notes")<=4000 and "strength_plans"."kind" in ('workout','scheduled') and jsonb_typeof("strength_plans"."exercises")='array' and jsonb_array_length("strength_plans"."exercises") between (case when "strength_plans"."is_draft" then 0 else 1 end) and 50 and (not "strength_plans"."is_draft" or "strength_plans"."kind"='workout') and ("strength_plans"."kind"='scheduled' or ("strength_plans"."time_block_id" is null and "strength_plans"."session_id" is null)));